const patient = $('Get Patient').first().json;
const clinic = $('Get Clinic Info').first().json;
const appt = $('Get Appointment').first().json;
const input = $('When Called by Alert Scheduler').first().json;
const clinicName = clinic.name || clinic.clinic_name || clinic.nombre || '';
const phone = '+' + String(patient.phone_number || '').replace(/\D/g, '');

const start = new Date(appt.start_datetime);
