    alert_instance_id: input.alert_instance_id || null,
    performed_by: input.performed_by || null,
    fields: {
      'patient.name': patient.name || 'Desconocido',
      'clinic.name': clinicName,
      'appointment.date': date,
      'appointment.hour': hour,
      'appointment.professional_name': appt.professional_name || 'Sin doctor asignado'
    }
  }
}];

const patient = $('Get Patient').first().json;
const clinic = $('Get Clinic Info').first().json;
const inv = $('Get Invoice').first().json;
const input = $('When Called by Alert Scheduler').first().json;
const clinicName = clinic.name || clinic.clinic_name || clinic.nombre || '';
const phone = '+' + String(patient.phone_number || '').replace(/\D/g, '');

const pending = (Number(inv.total) - Number(inv.paid_amount || 0)).toFixed(2);
const amountFormatted = `${inv.currency || ''} ${pending}`.trim();
const dueDateFormatted = new Date(inv.due_date).toLocaleDateString('es-UY', { day: 'numeric', month: 'long', year: 'numeric' });

return [{
  json: {
    phone,
    alert_instance_id: input.alert_instance_id || null,
    performed_by: input.performed_by || null,
    fields: {
      'patient.name': patient.name || '',
      'clinic.name': clinicName,
      'invoice.doc_no': inv.doc_no || '',
      'invoice.amount_formatted': amountFormatted,
      'invoice.due_date_formatted': dueDateFormatted
    }
  }
}];

const resolved = $input.first().json;
const tpl = $('Get Template Config').first().json;
const schema = tpl.variables_schema || {};

const variables = {};
for (const [metaVarName, fieldKey] of Object.entries(schema)) {
  if (!(fieldKey in resolved.fields)) {
    return [{ json: { __error: true, code: 500, message: `variables_schema references unknown field "${fieldKey}" for template "${tpl.code}". Available fields: ${Object.keys(resolved.fields).join(', ')}` } }];
  }
  variables[metaVarName] = resolved.fields[fieldKey];
}

return [{
  json: {
    phone: resolved.phone,
    meta_template_name: tpl.code,
    meta_language: tpl.provider_language || 'es',
    variables,
    alert_instance_id: resolved.alert_instance_id || null,
    performed_by: resolved.performed_by || null
  }
}];

