// Same system_configurations keys (whatsapp_test_mode_enabled / whatsapp_test_phone_whitelist)
// that gate the inbound WhatsApp agent in Whats App.json — a single shared whitelist for
// both directions, per product decision.
const cfg = $input.first().json;
const payload = $('Map Variables via Schema').first().json;
const phone = payload.phone;

const testModeEnabled = !!cfg.whatsapp_test_mode_enabled;
const rawList = cfg.whatsapp_test_phone_whitelist || '';
const whitelist = rawList
  .split(',')
  .map((p) => '+' + String(p).trim().replace(/\D/g, ''))
  .filter((p) => p !== '+');

const isWhitelisted = whitelist.includes(phone);
const allowed = !testModeEnabled || isWhitelisted;

return [{
  json: {
    ...payload,
    allowed,
    is_test_mode: testModeEnabled,
    is_whitelisted: isWhitelisted
  }
}];

const input = $("Prepare Send Payload").first().json;
const templates = $input.all().map((i) => i.json);

const matches = templates.filter((t) => t.name === input.meta_template_name);
const template =
  matches.find((t) => t.language === input.meta_language) || matches[0];

if (!template) {
  return [
    {
      json: {
        __error: true,
        code: 404,
        message: `No WHATSAPP template found in YCloud for meta_template_name="${input.meta_template_name}" and meta_language="${input.meta_language}"`,
      },
    },
  ];
}

const status = template.status || template.meta_status;
if (status !== "APPROVED") {
  return [
    {
      json: {
        __error: true,
        code: 409,
        message: `Template "${input.meta_template_name}" is not approved yet (status: ${status || "PENDING"})`,
      },
    },
  ];
}

if (!template.wabaId) {
  return [
    {
      json: {
        __error: true,
        code: 500,
        message: `Template "${input.meta_template_name}" has no wabaId on the YCloud response`,
      },
    },
  ];
}

const bodyComponent = Array.isArray(template.components)
  ? template.components.find((c) => String(c.type).toUpperCase() === "BODY")
  : null;
const placeholderOrder = [];
const seenPlaceholders = new Set();
if (bodyComponent && typeof bodyComponent.text === "string") {
  const found = bodyComponent.text.match(/\{\{\s*([^{}]+?)\s*\}\}/g) || [];
  found.forEach((m) => {
    const name = m.replace(/[{}]/g, "").trim();
    if (!seenPlaceholders.has(name)) {
      seenPlaceholders.add(name);
      placeholderOrder.push(name);
    }
  });
}
const placeholderNames = new Set(placeholderOrder);
const providedNames = new Set(Object.keys(input.variables || {}));
const missing = [...placeholderNames].filter((n) => !providedNames.has(n));
const extra = [...providedNames].filter((n) => !placeholderNames.has(n));
if (missing.length || extra.length) {
  return [
    {
      json: {
        __error: true,
        code: 400,
        message: `Variable mismatch for template "${input.meta_template_name}": missing=[${missing.join(", ")}] extra=[${extra.join(", ")}]. The template on Meta changed — update variables_schema on this CommunicationTemplate.`,
      },
    },
  ];
}

return [
  {
    json: {
      ...input,
      template_code: template.name,
      wabaId: template.wabaId,
      template_variable_order: placeholderOrder,
    },
  },
];

